def _disp(v,unit):
 if unit=="USD": return money(v)
 if unit=="%": return (f"{v*100:.0f}%" if abs(v*100-round(v*100))<1e-9 else f"{v*100:.1f}%")
 if unit=="days": return f"{int(v)} days"
 return str(v)
def _wrap(block,fields,pfx):
 if not block: return block
 out=dict(block)
 for k,(unit,status,formula) in fields.items():
  if k in block and block[k] is not None:
   out[k]=N(f"{pfx}.{k}",block[k],_disp(block[k],unit),unit,status,formula)
 return out
def _seller_summary(sv,pfx):
 rec=sv["recommendation"]; base=rec["base"]
 return {"route":rec["route"],"route_values":{k:(N(f"{pfx}.route_value.{k.lower().replace(' ','_')}",v,money(v),"USD","COMPUTED","recompute_model.recommend base value") if v is not None else None) for k,v in base.items()},"scenario_routes":{s:sv["scenarios"][s]["route"] for s in ("bear","base","bull")},"audit":rec["audit"]}
GLOSSARY={"Utilization":"The share of hours a rented server is actually earning money.","Drain":"Finishing or moving the running compute jobs so the server can be shipped.","ECC":"Error-correcting memory: it fixes small memory errors and reports the ones it cannot fix.","SXM":"NVIDIA's socketed GPU module that plugs into a shared board instead of a PCIe slot.","NVLink":"NVIDIA's high-speed link that lets the GPUs in one server share data directly.","PUE":"Power usage effectiveness: total data-center power divided by the power the servers use.","Colocation":"Renting rack space, power and cooling in someone else's data center.","GPU-hour":"One GPU rented for one hour; the unit rental prices are quoted in.","Marketplace cut":"The share of rental revenue the compute marketplace keeps.","Asking price":"The price the seller lists the server at.","Buyer total":"What the buyer pays: asking price plus freight and insurance, before tax.","Seller net":"What the seller keeps after the selling fee and shipping.","Freight":"The cost of shipping the server.","Insurance":"Shipping insurance, here 0.5% of the asking price.","Sales tax":"State tax on the purchase; not included in the buyer total.","Health score":"A 0 to 100 score built from the server's test results and condition.","Diagnostic":"NVIDIA's DCGM test suite. Level 1 checks software, level 2 adds memory and PCIe, level 3 adds compute, bandwidth, stress and power tests, level 4 adds memtest and a power-spike pulse test.","Thermal throttle":"A GPU slowing itself down because it ran too hot.","Row remapping":"How A100 and H100 GPUs repair themselves: a memory row that produced errors is permanently swapped for a spare row.","Remap failure":"The GPU has run out of spare memory rows; NVIDIA guidance is to stop running work on it and replace it.","Power brake":"A hardware signal that forces the GPU to slow down because the power supply cannot deliver enough current.","Power-on hours":"Total hours the server has been switched on.","Dwell time":"How long a listed server waits before it sells.","Survival curve":"The chance a listed server is still unsold on each day.","Harvest":"Taking a server apart and selling its working parts.","Recycle":"Recovering materials from hardware that cannot be sold or reused.","Repair":"Replacing a failed part so the server can be sold as working.","Escrow":"The buyer's payment is held by a third party until the buyer confirms delivery.","Inspection window":"The days after delivery the buyer has to report a mismatch.","Sanitization":"Erasing all stored data before the server changes hands.","NIST SP 800-88":"The US government guideline for securely erasing storage media.","Interruptible job":"A compute job that can be stopped and resumed, so a sold server can be freed quickly.","Market decay":"How much a server's resale value falls each month."}
def _evidence(seller):
    """Which NVIDIA outputs this grade was read from (SIMULATED files in NVIDIA's formats for the demo)."""
    from .seed_listings import NVIDIA_PROVENANCE
    p = NVIDIA_PROVENANCE.get(seller)
    if not p:
        return None
    return {"status": "SIMULATED", "files": [f"data/demo_inputs/{seller}/{f}" for f in ("dcgm_diag.json", "nvidia_smi.xml", "kernel.log", "chassis.json")],
            "sources": p["sources"], "gpu_serials": {str(k): v for k, v in p["gpu_serials"].items()},
            "nvidia_findings": [{k: f.get(k) for k in ("gpu", "test", "code", "name", "severity_name", "category", "message", "nvidia_next_step")}
                                for f in p["nvidia_findings"] if f.get("name") != "CASCADE"],
            "notes": p["notes"], "method": "engine/nvidia_reader.py reads NVIDIA output; engine/diagnostics.py grades it. ReCompute runs no GPU tests."}


